verus! {
    fn is_even(x: i32) -> bool {
        x % 2 == 0
    }

    fn remove_odd_numbers(arr: &[i32]) -> Vec<i32>
        ensures
            forall |i: int| (0 <= i < arr.len() as int && is_even(arr[i as usize])) ==> 
                exists |j: int| (0 <= j < result.len() as int && result[j as usize] == arr[i as usize]),
            result.len() <= arr.len(),
    {
        let mut result: Vec<i32> = Vec::new();
        let mut idx: usize = 0;

        while idx < arr.len()
            invariant
                idx <= arr.len(),
                result.len() <= idx,
                forall |i: int| (0 <= i < idx as int && is_even(arr[i as usize])) ==> 
                    exists |j: int| (0 <= j < result.len() as int && result[j as usize] == arr[i as usize]),
        {
            if is_even(arr[idx]) {
                result.push(arr[idx]);
            }
            idx = idx + 1;
        }
        result
    }
}

